mapper.select:
SELECT EXISTS(
SELECT 1
FROM members
WHERE LOWER(email) = LOWER(#{email})
AND member_id <> #{memberId}
)

SELECT personal_or_corporate
FROM members
WHERE member_id = #{memberId}

SELECT COUNT(*)
FROM member_additional_addresses
WHERE member_id = #{memberId}

mapper.delete:
DELETE FROM member_additional_addresses
WHERE member_id = #{memberId}
AND member_address_id = #{memberAddressId}

mapper.select:
SELECT COUNT(*)
FROM member_favorites mf
JOIN products p ON p.product_id = mf.product_id
WHERE mf.member_id = #{memberId}
AND p.sale_start_at <= #{now}
AND (p.sale_end_at IS NULL OR p.sale_end_at > #{now})

SELECT DISTINCT pv.product_id, c.color_code, c.sort_order FROM product_variants pv JOIN colors c ON c.color_id = pv.color_id WHERE pv.product_id IN
#{productId}
ORDER BY pv.product_id ASC, c.sort_order ASC

SELECT EXISTS(
SELECT 1
FROM member_favorites
WHERE member_id = #{memberId}
AND product_id = #{productId}
)

mapper.delete:
DELETE FROM member_favorites
WHERE member_id = #{memberId}
AND product_id = #{productId}
